import { randomUUID } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import { mkdir } from 'node:fs/promises';
import path from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { fileURLToPath } from 'node:url';
import { Router, type Request, type Response } from 'express';
import multer from 'multer';
import { authMiddleware } from '../auth.js';
import {
  createMessage,
  getChatById,
  listMessages,
  saveMedia,
  setLastRead,
  touchChat,
  updateMessageStatus,
} from '../store.js';
import type { Message, User } from '../types.js';
import { emitToChat, emitToUser, isUserOnline } from '../ws.js';

type AuthedRequest = Request & { user: User };
const uploadsDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../uploads');
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024 } });

function asAuthed(req: Request): AuthedRequest {
  return req as AuthedRequest;
}

function requireMember(chatId: string, userId: string, res: Response) {
  const chat = getChatById(chatId);
  if (!chat) {
    res.status(404).json({ error: 'not_found' });
    return null;
  }
  if (!chat.memberIds.includes(userId)) {
    res.status(403).json({ error: 'forbidden' });
    return null;
  }
  return chat;
}

function broadcastNew(chatId: string, message: Message, senderId: string): void {
  emitToChat(chatId, 'message.new', { message });
  const chat = getChatById(chatId);
  if (!chat) return;
  for (const memberId of chat.memberIds) {
    if (memberId === senderId || !isUserOnline(memberId)) continue;
    const updated = updateMessageStatus(message.id, 'delivered');
    if (!updated) continue;
    const statusPayload = { messageId: updated.id, chatId, status: updated.status };
    emitToUser(memberId, 'message.status', statusPayload);
    emitToUser(senderId, 'message.status', statusPayload);
  }
  emitToChat(chatId, 'chat.updated', { chatId });
}

function isAudioMime(mime: string): boolean {
  const m = mime.toLowerCase();
  return (
    m.includes('m4a') ||
    m.includes('aac') ||
    m.includes('mp4') ||
    m.includes('webm') ||
    m === 'audio/mp4' ||
    m === 'audio/aac' ||
    m === 'audio/webm'
  );
}

export const messagesRouter = Router();

messagesRouter.get('/chats/:chatId/messages', authMiddleware, (req, res) => {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;
  let limit = 50;
  if (typeof req.query.limit === 'string' && req.query.limit.length > 0) {
    const n = Number(req.query.limit);
    if (!Number.isFinite(n) || n < 1) {
      res.status(400).json({ error: 'invalid' });
      return;
    }
    limit = Math.min(100, Math.floor(n));
  }
  const before = typeof req.query.before === 'string' ? req.query.before : undefined;
  res.json(listMessages(chatId, { before, limit }).slice().reverse());
});

messagesRouter.post('/chats/:chatId/messages', authMiddleware, (req, res) => {
  const contentType = String(req.headers['content-type'] ?? '');
  if (contentType.includes('multipart/form-data')) {
    upload.single('audio')(req, res, (err: unknown) => {
      if (err) {
        res.status(400).json({ error: 'invalid_audio' });
        return;
      }
      void handleAudio(req, res);
    });
    return;
  }
  handleText(req, res);
});

function handleText(req: Request, res: Response): void {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;
  const body = req.body as { type?: unknown; text?: unknown };
  if (body.type !== 'text' || typeof body.text !== 'string') {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (body.text.length < 1 || body.text.length > 4000) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  const message = createMessage({
    chatId,
    senderId: user.id,
    type: 'text',
    text: body.text,
    audioId: null,
    audioDurationMs: null,
    status: 'sent',
  });
  touchChat(chatId);
  broadcastNew(chatId, message, user.id);
  res.status(201).json(message);
}

async function handleAudio(req: Request, res: Response): Promise<void> {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;
  const type = typeof req.body?.type === 'string' ? req.body.type : undefined;
  const durationMs = Number(req.body?.durationMs);
  const file = req.file;
  if (
    type !== 'audio' ||
    !file ||
    !Number.isFinite(durationMs) ||
    durationMs < 1 ||
    durationMs > 60000 ||
    file.size <= 0 ||
    file.size > 5 * 1024 * 1024 ||
    !isAudioMime(file.mimetype || '')
  ) {
    res.status(400).json({ error: 'invalid_audio' });
    return;
  }
  const id = randomUUID();
  await mkdir(uploadsDir, { recursive: true });
  const dest = path.join(uploadsDir, id);
  await pipeline(Readable.from(file.buffer), createWriteStream(dest));
  const media = saveMedia({
    id,
    path: dest,
    mime: file.mimetype || 'audio/mp4',
    size: file.size,
  });
  const message = createMessage({
    chatId,
    senderId: user.id,
    type: 'audio',
    text: null,
    audioId: media.id,
    audioDurationMs: Math.floor(durationMs),
    status: 'sent',
  });
  touchChat(chatId);
  broadcastNew(chatId, message, user.id);
  res.status(201).json(message);
}

messagesRouter.post('/chats/:chatId/read', authMiddleware, (req, res) => {
  const { user } = asAuthed(req);
  const chatId = req.params.chatId as string;
  if (!requireMember(chatId, user.id, res)) return;
  const lastReadMessageId = (req.body as { lastReadMessageId?: unknown })?.lastReadMessageId;
  if (typeof lastReadMessageId !== 'string' || lastReadMessageId.length < 1) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  setLastRead(chatId, user.id, lastReadMessageId);
  res.status(204).send();
});
